import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Handler;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class AvoidPitfallsDemo {

    private static final Logger log = Logger.getLogger(AvoidPitfallsDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger rootLogger = Logger.getLogger("");
        for (Handler handler : rootLogger.getHandlers()) {
            rootLogger.removeHandler(handler);
        }
        ConsoleHandler consoleHandler = new ConsoleHandler();
        consoleHandler.setFormatter(new BankLogFormatter());
        consoleHandler.setLevel(Level.ALL);
        rootLogger.addHandler(consoleHandler);
        rootLogger.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info(() -> "Linting behavioral answers for common pitfalls at " + BANK_NAME);

        AnswerLinter linter = new AnswerLinter();

        String weak = "The other team broke the transfer service and we fixed it. "
                + "We looked at it and we think it got better afterwards.";

        String strong = "The transfer service was failing at peak. I owned the fix. "
                + "I traced it to a missing index, I added the index, and I reduced "
                + "error rate from 12% to 0.3% within 2 hours.";

        log.warning("Linting the WEAK answer:");
        linter.lint(weak);

        log.info("Linting the STRONG answer:");
        linter.lint(strong);
    }
}

// ─── Would be in lint/AnswerLinter.java in a real project ───
class AnswerLinter {
    private static final Logger log = Logger.getLogger(AnswerLinter.class.getName());
    private static final String[] BLAME_WORDS = {"the other team", "their fault", "they broke",
            "because of him", "because of her", "someone else"};

    int lint(String answer) {
        int issues = 0;
        String lower = answer.toLowerCase();

        // Pitfall 1: blame language.
        for (String blame : BLAME_WORDS) {
            if (lower.contains(blame)) {
                issues++;
                log.warning(() -> "BLAME detected: '" + blame
                        + "'. Focus on what YOU did, not whose fault it was.");
            }
        }

        // Pitfall 2: too much "we", not enough "I".
        int weCount = countWord(lower, "we");
        int iCount = countWord(lower, "i");
        if (weCount > iCount) {
            issues++;
            log.warning(() -> "Too many 'we' (" + weCount + ") vs 'I' (" + iCount
                    + "). Say what YOU personally did.");
        }

        // Pitfall 3: no measurable number.
        if (!answer.matches(".*\\d.*")) {
            issues++;
            log.warning("No measurable result. Add a number: % improved, ms saved, errors reduced.");
        }

        final int finalIssues = issues;
        log.info(() -> "Lint issues: " + finalIssues + " "
                + (finalIssues == 0 ? "— clean, interview ready." : "— fix these before the interview."));
        return issues;
    }

    // Count standalone word occurrences (surrounded by non-letters).
    private int countWord(String text, String word) {
        int count = 0;
        String[] tokens = text.split("[^a-z]+");
        for (String t : tokens) {
            if (t.equals(word)) {
                count++;
            }
        }
        return count;
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tY-%1$tm-%1$td %1$tH:%1$tM:%1$tS.%1$tL %2$-7s [%3$s] %4$s%n",
                record.getMillis(),
                record.getLevel().getName(),
                record.getSourceClassName() != null
                        ? record.getSourceClassName().substring(
                                record.getSourceClassName().lastIndexOf('.') + 1)
                        : "Unknown",
                record.getMessage());
    }
}
